Plugins.Require("pay_activity", "common.config.FisherManGiftConfig")
---@type IPayActivity
local IPayActivity = Plugins.Require("pay_activity", "common.class.IPayActivity")
---@class FisherManGift : IPayActivity
local FisherManGift = class("FisherManGift", IPayActivity)
---@type FisherManGiftConfig
local FisherManGiftConfig = T(Global, "FisherManGiftConfig")
---@type ReportEvent
local ReportEvent = T(Global, "ReportEvent")
---@type EventConfig
local EventConfig = T(Global, "EventConfig")
EventConfig:registerEvent("fisherman_gift_click", {})
EventConfig:registerEvent("fisherman_fish_click", {})
EventConfig:registerEvent("fisherman_gift_get", {
    ["fisherman_fish_count"] = "number",
    ["fisherman_gift_id"] = "number",
})

function FisherManGift:initDataInfo()
    self:initInfoKey("Record", {})
    self:initInfoKey("First", isClient)
    if isClient then
        self:updateRedDot(self:getLotteryPrice() == 0)
        self.info:addKeyObserver("Record", function()
            self:updateRedDot(self:getLotteryPrice() == 0)
        end)
    else
        self:registerC2SFunc("tryFishing")
    end
end

function FisherManGift:tryFishing()
    local record = self.info:getValue("Record")
    local price = self:getLotteryPrice()
    if not price then
        return
    end
    if isClient then
        PayHelper.checkMoney(CurrencyId.GCube, price, function(success)
            if success then
                self:runServerFunc("tryFishing")
            end
        end)
    else
        local times = TableUtil.getTableSize(record) + 1
        local cfg = FisherManGiftConfig:tryLottery(record,self.player)
        if not cfg then
            return
        end
        local theRewardId=FisherManGiftConfig:getRewardId(cfg,self.player)
        --if not self:canReward(theRewardId) then
        --    return
        --end
        PayHelper.payMoneySync(self.player, times, CurrencyId.GCube, price, function()
            self:doReward(theRewardId)
            table.insert(record, theRewardId)
            self.info:setValue("Record", record)
            ReportEvent.reportEvent(self.player.userId, "fisherman_gift_get", false, {
                fisherman_fish_count = TableUtil.getTableSize(record),
                fisherman_gift_id = theRewardId,
            })
        end)
    end
end

function FisherManGift:getLotteryPrice()
    local record = self.info:getValue("Record")
    return FisherManGiftConfig:getLotteryPrice(record)
end

function FisherManGift:onStop()
    self:updateRedDot(false)
end

return FisherManGift